<?php use Hls\Http\View as V; $max=max($inflow,$outflow,1); ?>
<form class="panel form-grid" method="get"><label>Mulai<input type="date" name="start" value="<?= V::escape($start) ?>"></label><label>Sampai<input type="date" name="end" value="<?= V::escape($end) ?>"></label><label>Cabang<select name="branch_id"><option value="0">Semua cabang dalam akses</option><?php foreach($branches as $b): if($access->branch((int)$b['id'])): ?><option value="<?= (int)$b['id'] ?>" <?= $branch_id===(int)$b['id']?'selected':'' ?>><?= V::escape($b['code'].' - '.$b['name']) ?></option><?php endif; endforeach ?></select></label><button class="button primary">Terapkan</button></form>
<div class="kpi-grid"><?php foreach([['Saldo Kas & Bank',$balance,'Posisi akhir periode'],['Piutang',$receivable,'Invoice aktif'],['Utang',$payable,'Tagihan posted'],['Penerimaan',$inflow,$start.' s/d '.$end],['Pengeluaran',$outflow,'Expense dan pembayaran supplier']] as $k): ?><article class="panel kpi-card"><span class="kpi-label"><?= V::escape($k[0]) ?></span><strong class="kpi-value"><?= \Hls\Http\View::money($k[1]) ?></strong><small><?= V::escape($k[2]) ?></small></article><?php endforeach ?></div>
<section class="panel"><h2>Penerimaan vs Pengeluaran</h2><p>Penerimaan: <?= \Hls\Http\View::money($inflow) ?></p><div style="height:12px;background:#087ccb;width:<?= ($inflow/$max)*100 ?>%;max-width:100%;border-radius:4px"></div><p>Pengeluaran: <?= \Hls\Http\View::money($outflow) ?></p><div style="height:12px;background:#0D3972;width:<?= ($outflow/$max)*100 ?>%;max-width:100%;border-radius:4px"></div></section>